def main():
    s = input().strip()
    n = len(s)
    pos = 0

    # 转换字符串
    for i in range(n):
        s += s[pos]  # 追加 pos 位置的字符
        s = s[:pos] + '?' + s[pos + 1:]  # 标记该字符为已用
        c = 0

        if i == n - 1:
            break

        # 找下一个要移动到末尾的字符
        while c < 2:
            if s[pos] != '?':
                c += 1
            pos += 1

            if c == 2:
                pos -= 1  # 移回到上一个有效位置
                break

    # 打印转换后的字符串
    result = ''.join([char for char in s if char != '?'])
    print(result)

if __name__ == "__main__":
    main()

